// Tests for the three NASA rules that were quoted but not used (the NASA-style review, PO-11; src/nasa-rules.js, the
// cells in src/config.js and the machine in src/engine.js): the cabin CO2 around a logged headache with its 7-day
// average, body mass against the loss levels of NASA's nutrition report, and hearing judged by its shift from the
// person's own pre-flight test. Run: npm test (Node 18+). Code generated by Claude (Anthropic), an AI system.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createMachine, checkNorm, STATUS } from '../src/engine.js';
import { CELLS, CREW, SHIP } from '../src/config.js';
import { exampleFlight, MISSION } from '../src/demo-crew.js';
import { assess, measureState, LEVEL, SLOW_MEASURES } from '../src/state-levels.js';
import { eventProblem } from '../src/security.js';
import {
  co2Link, co2Around, co2Short, co2Words, headacheToday, headacheList, CO2_RULES, agoText,
  massLevels, massLines, massWords, hearingRule, hearingState, hearingRangeText, hearingBand, hearingLines, hearingWords,
} from '../src/nasa-rules.js';

const HOUR = 3600 * 1000;
const DAY = 24 * HOUR;
const NOW = new Date('2026-11-15T12:00:00Z');
const at = (hoursAgo) => new Date(NOW.getTime() - hoursAgo * HOUR).toISOString();
const cell = (indicator) => CELLS.find((c) => c.indicator === indicator);
const STATE = { aiWorks: true, doctorOnBoard: false, linkToEarth: true };
const FLIGHT = { launch: '2026-06-01T12:00:00Z', today: NOW.toISOString(), landing: '2026-12-10T12:00:00Z' };
const TOM = CREW.find((p) => p.id === 'crew-1');
const make = (mission = FLIGHT) => createMachine({ cells: CELLS, crew: [...CREW, SHIP], state: STATE, mission });
const put = (m, indicator, value, time, person = 'crew-1') => m.receive({ person, source: 'test', indicator, value, time });

// ---------- cabin CO2 and headaches ----------
test('the CO2 and headache link is data on the symptom cell, from Law et al. 2014 and NASA\'s CO2 brief, as checked', () => {
  const link = co2Link();
  assert.equal(link.symptom, 'headache');
  assert.equal(link.measure, 'co2');
  assert.equal(link.days, 7);
  assert.equal(link.below, 2.5);
  assert.match(link.text, /odds of a reported headache doubled/);
  assert.match(link.src.url, /24806559/);
  assert.match(link.src2.url, /ochmo-tb-004-carbon-dioxide\.pdf$/);
  assert.equal(cell('co2').norm.max, 3, "NASA-STD-3001 Vol 2 [V2 6004]: one-hour average at most 3 mmHg");
});

test('the cabin CO2 before a time: the latest reading at or before it, the 7-day average, and nothing from after it', () => {
  const co2 = [[200, 9], [150, 2.0], [100, 2.4], [30, 2.8], [6, 3.4], [-2, 7]].map(([h, v]) => ({ time: at(h), value: v }));
  const ctx = co2Around(co2, NOW);
  assert.equal(ctx.latest.value, 3.4);
  assert.equal(ctx.latest.hoursBefore, 6);
  assert.equal(ctx.latest.overLimit, true);
  assert.equal(ctx.average.count, 4, 'the four readings of the 7 days before; the one of 200 h ago and the one after are left out');
  assert.equal(ctx.average.value, 2.65);
  assert.equal(ctx.average.notBelowLine, true);
  assert.equal(ctx.limit, 3);
  assert.equal(ctx.line, 2.5);
  assert.equal(co2Around([{ time: at(1), value: 2 }], NOW).average.notBelowLine, false);
  const empty = co2Around([], NOW);
  assert.equal(empty.latest, null);
  assert.equal(empty.average, null);
  assert.equal(co2Around(co2, 'not a time'), null);
  // The technical view sends typed numbers as text: still read.
  assert.equal(co2Around([{ time: at(1), value: '2.2' }], NOW).latest.value, 2.2);
});

test('the words: the values, how long before, NASA\'s 3 mmHg as a one-hour average, and the 2.5 mmHg of the study', () => {
  const ctx = co2Around([{ time: at(4), value: 3.4 }, { time: at(30), value: 2.0 }], NOW);
  assert.equal(co2Short(ctx), "cabin CO2 before it 3.4 mmHg (latest, GMT 319/08:00, 4 h before), 7-day average 2.7 mmHg; NASA's limit is 3 mmHg as a one-hour average");
  const words = co2Words(ctx).join(' ');
  assert.match(words, /Latest cabin CO2 before it: 3\.4 mmHg at GMT 319\/08:00, 4 h before, above NASA's limit of 3 mmHg \(a limit on the one-hour average; this is a single reading\)\./);
  assert.match(words, /7-day average: 2\.7 mmHg from 2 readings, not below 2\.5 mmHg/);
  assert.equal(co2Short(co2Around([], NOW)), 'no cabin CO2 reading in the 7 days before it');
  assert.equal(agoText(0.2), 'less than 1 h');
  assert.equal(agoText(30), '30 h');
  assert.equal(agoText(72), '3 days');
});

test('Today shows a headache of the last 24 hours with its cabin CO2; the symptom page lists the latest headaches', () => {
  const m = make();
  put(m, 'co2', 2.9, at(8), 'ship');
  put(m, 'symptoms', { symptom: 'headache', severity: 3 }, at(30));
  put(m, 'symptoms', { symptom: 'backPain', severity: 6 }, at(2));
  assert.equal(headacheToday(m.history('crew-1', 'symptoms'), m.history('ship', 'co2'), NOW), null, 'a headache of 30 hours ago and a back pain: nothing on Today');
  put(m, 'symptoms', { symptom: 'headache', severity: 4 }, at(5));
  const today = headacheToday(m.history('crew-1', 'symptoms'), m.history('ship', 'co2'), NOW);
  assert.equal(today.entry.value.severity, 4);
  assert.equal(today.co2.latest.value, 2.9);
  assert.equal(CO2_RULES.todayHours, 24);
  assert.equal(CO2_RULES.draft, true);
  for (let i = 0; i < 7; i += 1) put(m, 'symptoms', { symptom: 'headache', severity: 1 }, at(100 + i * 24));
  const list = headacheList(m.history('crew-1', 'symptoms'), m.history('ship', 'co2'));
  assert.equal(list.length, CO2_RULES.listMax);
  assert.equal(list[0].entry.value.severity, 4, 'newest first');
  assert.ok(list.every((x) => x.entry.value.symptom === 'headache'));
});

test('the example flight: the later headache of crew member 3 falls on a day of higher cabin CO2, and the page can show it', () => {
  const m = make(MISSION);
  for (const ev of exampleFlight(CREW)) if (ev.kind === 'reading') m.receive({ ...ev.reading, person: ev.person, time: ev.time });
  const [late] = headacheList(m.history('crew-3', 'symptoms'), m.history('ship', 'co2'));
  assert.equal(Math.floor((new Date(late.entry.time) - new Date(MISSION.launch)) / DAY), 74);
  // The ship's made-up CO2 rises every 37th day: that day's reading is above the week's average, and at or above the
  // 2.8 mmHg from which NASA's CO2 brief reports headaches (anecdotal).
  assert.ok(late.co2.latest.value > late.co2.average.value, `${late.co2.latest.value} against ${late.co2.average.value} mmHg`);
  assert.ok(late.co2.latest.value >= 2.8, `${late.co2.latest.value} mmHg`);
});

// ---------- body mass ----------
test('body mass: the band ends at a loss of 5%, the red limit is a loss of 10%, both drafts from NASA\'s nutrition report', () => {
  const c = cell('bodyMass');
  assert.equal(c.normType, 'range');
  assert.deepEqual(c.norm, { min: 95, max: null });
  assert.equal(c.draft, true);
  assert.equal(c.red.length, 1);
  assert.deepEqual([c.red[0].when, c.red[0].value, c.red[0].level, c.red[0].draft], ['atOrBelow', 90, 'action', true]);
  assert.match(c.red[0].url, /20150000512/);
  assert.match(c.norms.personalEarth.text, /worthy of concern.*clinically significant/);
  assert.deepEqual(massLevels(), { concernBelow: 95, significantAt: 90, src: massLevels().src });
  assert.deepEqual(massLines().map((l) => l.v), [95, 90]);
  for (const l of massLines()) assert.match(l.label, /\(NASA, draft\)$/);
});

test('body mass in words: a loss below 5%, past 5% (worthy of concern) and at 10% (clinically significant)', () => {
  assert.equal(massWords(96.8), "Your last reading is 96.8% of your pre-flight mass: a loss of 3.2%. NASA's nutrition report calls a loss of more than 5% of pre-flight mass worthy of concern, and a loss of 10% clinically significant. The lines on the chart, at 95% and 90%, are drafts here.");
  assert.equal(massWords(94.2), "Your last reading is 94.2% of your pre-flight mass: a loss of 5.8%. That is more than 5%, which NASA's nutrition report calls worthy of concern. The lines on the chart, at 95% and 90%, are drafts here.");
  assert.match(massWords(89.5), /a loss of 10\.5%\. That is a loss of 10% or more, which NASA's nutrition report calls clinically significant\./);
  assert.match(massWords(100.4), /0\.4% above it\./);
  assert.equal(massWords('abc'), null);
});

test('body mass in the levels: one reading past a loss of 5% is attention, a loss of 10% needs action at once', () => {
  const run = (value) => {
    const m = make();
    put(m, 'bodyMass', 100, '2026-05-20T08:00:00Z');
    put(m, 'bodyMass', value, at(10));
    return assess({ machine: m, person: TOM, cells: CELLS, mission: FLIGHT, now: NOW }).body.items.find((x) => x.cell && x.cell.indicator === 'bodyMass');
  };
  assert.equal(run(95.5), undefined);
  const concern = run(94.5);
  assert.equal(concern.kind, 'out');
  assert.equal(concern.level, LEVEL.ATTENTION);
  const significant = run(89);
  assert.equal(significant.kind, 'red');
  assert.equal(significant.level, LEVEL.ACTION);
  // A drop in the first month and then a plateau, as in ISS data, is not carried forward by a straight line.
  assert.ok(!SLOW_MEASURES.includes('bodyMass'));
});

// ---------- hearing ----------
test('hearing: the cell judges the shift from the own pre-flight test (NASA JSC 2015), WHO\'s 20 dB only as the second reference', () => {
  const c = cell('hearing');
  assert.equal(c.normType, 'baseline-shift');
  assert.deepEqual(c.norm, { shiftAtLeast: 10, fallback: { max: 20, maxExclusive: true } });
  assert.equal(c.draft, true);
  assert.equal(c.compareWith, 'personalEarth');
  assert.match(c.norms.personalEarth.text, /10 dB or more at 2000, 3000 and 4000 Hz since the pre-flight hearing test/);
  assert.match(c.norms.personalEarth.src.url, /20150011048/);
  assert.match(c.norms.earthGeneral.text, /500, 1000, 2000 and 4000 Hz/);
  assert.match(c.norms.spaceGeneral.src.url, /20240009887/);
  assert.deepEqual(hearingRule(), { shiftAtLeast: 10, whoBelow: 20 });
});

test('hearing in the machine: a shift of 10 dB or more from the latest test before launch is outside the norm', () => {
  const m = make();
  put(m, 'hearing', 25, '2026-03-01T08:00:00Z');
  put(m, 'hearing', 12, '2026-05-01T08:00:00Z'); // the latest test before launch
  const pre = m.history('crew-1', 'hearing');
  assert.equal(pre[0].status, STATUS.OUT, 'a test before launch is judged against WHO\'s 20 dB');
  assert.equal(pre[1].status, STATUS.OK);
  assert.equal(pre[1].shift, undefined);
  const ok = put(m, 'hearing', 21.9, at(48));
  assert.equal(ok.status, STATUS.OK, 'a shift of 9.9 dB, though above WHO\'s 20 dB');
  const step = ok.steps.find((s) => s.code === 'in-norm');
  assert.deepEqual([step.shift, step.baseline, step.baselineTime], [9.9, 12, '2026-05-01T08:00:00.000Z']);
  assert.equal(ok.steps.find((s) => s.code === 'norm-used').norm, 'personalEarth');
  const out = put(m, 'hearing', 22, at(24));
  assert.equal(out.status, STATUS.OUT);
  assert.equal(out.steps.find((s) => s.code === 'out-of-norm').shift, 10);
  const last = m.history('crew-1', 'hearing').slice(-1)[0];
  assert.deepEqual([last.shift, last.baseline], [10, 12]);
  assert.equal(put(m, 'hearing', -5, at(12)).status, STATUS.OK, 'a better threshold than before flight is fine');
});

test('hearing without a pre-flight test or without a mission: WHO\'s 20 dB stands in, as before', () => {
  const none = make(null);
  assert.equal(put(none, 'hearing', 19, at(5)).status, STATUS.OK);
  const twenty = put(none, 'hearing', 20, at(4));
  assert.equal(twenty.status, STATUS.OUT);
  assert.equal(twenty.steps.find((s) => s.code === 'norm-used').norm, 'earthGeneral');
  const noTest = make();
  assert.equal(put(noTest, 'hearing', 21, at(5)).status, STATUS.OUT, 'in flight with no test before launch');
  // The server's check knows no pre-flight test: any readable number of the measure is accepted, as before.
  assert.deepEqual(checkNorm(cell('hearing'), 35, null), { valid: true, inNorm: false, side: 'above', norm: 'earthGeneral' });
  assert.deepEqual(checkNorm(cell('hearing'), 'x', null), { valid: false });
  const e = { v: 1, kind: 'reading', time: at(1), person: 'crew-1', state: STATE, reading: { source: 'audiometer', indicator: 'hearing', value: -10 } };
  assert.equal(eventProblem(e, { now: NOW.getTime() }), null);
});

test('hearing in the levels and on the page: attention at a shift of 10 dB, the band and lines from the pre-flight test', () => {
  const m = make();
  put(m, 'hearing', 12, '2026-05-01T08:00:00Z');
  put(m, 'hearing', 14, at(24 * 60));
  const list = () => m.history('crew-1', 'hearing');
  assert.equal(hearingRangeText(list()), 'below 22 dB HL, less than 10 dB above your pre-flight test of 12 dB HL');
  assert.deepEqual(hearingBand(list()), { min: null, max: 22 });
  assert.deepEqual(hearingLines(list()).map((l) => l.v), [22], "WHO's 20 dB is too close to draw beside it");
  const words = hearingWords(list()).join(' ');
  assert.match(words, /Your pre-flight test: 12 dB HL, GMT 121\/08:00, the latest test before launch\./);
  assert.match(words, /Your last test, 14 dB HL, is 2 dB above it\./);
  assert.match(words, /low tones \(250 and 500 Hz\) in 60% of crewmembers/);
  const ms = measureState({ machine: m, person: TOM, cell: cell('hearing'), mission: FLIGHT, now: NOW });
  assert.deepEqual(ms.norm, { min: null, max: 22, maxExclusive: true }, 'the forecast uses the same band');
  put(m, 'hearing', 23, at(10));
  const item = assess({ machine: m, person: TOM, cells: CELLS, mission: FLIGHT, now: NOW }).body.items.find((x) => x.cell && x.cell.indicator === 'hearing');
  assert.equal(item.kind, 'out');
  assert.equal(item.level, LEVEL.ATTENTION);
  assert.match(hearingWords(list()).join(' '), /11 dB above it: a shift of 10 dB or more, which NASA counts as a mission-related shift/);
  // A low pre-flight test leaves room for WHO's line beside NASA's.
  const low = make();
  put(low, 'hearing', 0, '2026-05-01T08:00:00Z');
  put(low, 'hearing', 3, at(5));
  assert.deepEqual(hearingLines(low.history('crew-1', 'hearing')).map((l) => l.v), [10, 20]);
  // No pre-flight test: the words and the band say so.
  const none = make();
  put(none, 'hearing', 8, at(5));
  assert.equal(hearingState(none.history('crew-1', 'hearing')).baseline, null);
  assert.match(hearingRangeText(none.history('crew-1', 'hearing')), /WHO; no pre-flight test on record/);
  assert.match(hearingWords(none.history('crew-1', 'hearing')).join(' '), /No pre-flight test is on record/);
});

test('the example flight: no made-up person crosses the new lines, so Today stays as it was', () => {
  const m = make(MISSION);
  for (const ev of exampleFlight(CREW)) {
    if (ev.kind === 'reading') m.receive({ ...ev.reading, person: ev.person, time: ev.time });
    else m.review(ev.person, ev.time);
  }
  const now = new Date(MISSION.today);
  const levels = CREW.map((p) => { const a = assess({ machine: m, person: p, cells: CELLS, mission: MISSION, now }); return [p.id, a.body.level, a.psyche.level]; });
  assert.deepEqual(levels, [['crew-1', 0, 0], ['crew-2', 1, 0], ['crew-3', 0, 0], ['crew-4', 0, 2]]);
  for (const p of CREW) {
    for (const ind of ['bodyMass', 'hearing']) assert.ok(m.history(p.id, ind).every((x) => x.status !== STATUS.OUT), `${p.id} ${ind}`);
    assert.ok(m.history(p.id, 'hearing').filter((x) => new Date(x.time) >= new Date(MISSION.launch)).every((x) => Number.isFinite(x.shift)), `${p.id}: every test in flight is compared with the one before launch`);
  }
});
